use std::collections::HashMap;impl Solution{pub fn word_break(s:String,w:Vec<String>)->Vec<String>{fn f(i:usize,s:&str,w:&[String],m:&mut HashMap<usize,Vec<String>>)->Vec<String>{if let Some(v)=m.get(&i){return v.clone()}if i==s.len(){return vec![String::new()]}let mut r=vec![];for x in w{if i+x.len()<=s.len()&&&s[i..i+x.len()]==x{for t in f(i+x.len(),s,w,m){r.push(if t.is_empty(){x.clone()}else{format!("{} {}",x,t)});}}}m.insert(i,r.clone());r}f(0,&s,&w,&mut HashMap::new())}}
